"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["96470"],{55623(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.tamanho_maximo_bytes_invalido","status":422,"titulo":"O tamanho m\xe1ximo em bytes, quando presente, deve ser maior que zero"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.tamanho_maximo_bytes_invalido","requisitos":[],"oQueAconteceu":["O documento exigido pode declarar o tamanho m\xe1ximo, em bytes, do arquivo que o candidato envia.\\nQuando o valor \xe9 informado, ele precisa ser maior que zero. A defini\xe7\xe3o trouxe um valor igual a\\nzero ou negativo.","\xc9 uma confer\xeancia de forma, feita antes de o sistema consultar o tipo de documento, as fases ou\\nas demais configura\xe7\xf5es do processo. Ela examina as exig\xeancias na ordem recebida e para na\\nprimeira que tem defeito; dentro dessa exig\xeancia, os defeitos de forma aparecem juntos."],"comoResolver":["Informe o tamanho m\xe1ximo como um n\xfamero de bytes maior que zero. Se a exig\xeancia n\xe3o deve ter\\nlimite geral, omita o campo. Isso n\xe3o garante o teto de 10 MB do sistema para arquivos de\\ninscri\xe7\xe3o: a exig\xeancia tamb\xe9m pode ter limite espec\xedfico por formato na lista de formatos\\naceitos, e vale o menor entre o limite do formato e o geral. O teto de 10 MB s\xf3 vale quando\\nnenhum dos dois est\xe1 definido, e nenhum arquivo passa de 20 MB, qualquer que seja a\\nexig\xeancia."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);